function output_path = generate_onshape_3d_sketch(nodes, elements_geom, options)
% GENERATE_ONSHAPE_3D_SKETCH Generate an Onshape FeatureScript snippet for 3D frame centerlines.
%
% The generated file is intentionally limited to 3D centerline geometry only.
% It emits one opPolyline wire body per frame element and does not attempt to
% create tubes, cope cuts, or end treatments.
%
% Inputs:
%   nodes         - Nx3 matrix [x,y,z] in frame coordinates [Xrear+, Yright+, Zup+]
%   elements_geom - struct with .connectivity (Mx2)
%   options       - optional struct with:
%       .output_dir         - output directory (default: './output')
%       .filename           - output filename (default: 'fsae_frame_onshape_3d_sketch.fs')
%       .feature_name       - Onshape feature name (default: 'FSAE Frame 3D Sketch')
%       .coordinate_comment - extra note written into the file header
%
% Output:
%   output_path - full path to the generated FeatureScript file

    if nargin < 3
        options = struct();
    end

    validateattributes(nodes, {'numeric'}, {'2d', 'ncols', 3, 'finite', 'real'}, ...
        mfilename, 'nodes');
    assert(isstruct(elements_geom) && isfield(elements_geom, 'connectivity'), ...
        'generate_onshape_3d_sketch:MissingConnectivity', ...
        'elements_geom.connectivity is required.');

    connectivity = elements_geom.connectivity;
    validateattributes(connectivity, {'numeric'}, {'2d', 'ncols', 2, 'integer', 'positive'}, ...
        mfilename, 'elements_geom.connectivity');
    assert(all(connectivity(:) <= size(nodes, 1)), ...
        'generate_onshape_3d_sketch:ConnectivityOutOfRange', ...
        'elements_geom.connectivity references node indices outside the nodes array.');

    opts = parse_options(options);
    onshape_nodes = frame_to_onshape(nodes);
    unique_segments = unique(sort(connectivity, 2), 'rows', 'stable');

    lines = {};
    lines{end+1} = '// ============================================================';
    lines{end+1} = '// FSAE Frame 3D Sketch for Onshape';
    lines{end+1} = ['// Auto-generated by MATLAB: ' datestr(now, 'yyyy-mm-dd HH:MM:SS')];
    lines{end+1} = '//';
    lines{end+1} = '// Usage:';
    lines{end+1} = '//   1. Create a new Feature Studio in Onshape.';
    lines{end+1} = '//   2. Keep the auto-generated FeatureScript header/import lines.';
    lines{end+1} = '//   3. Paste the feature below into that studio.';
    lines{end+1} = '//   4. Add the custom feature to a Part Studio and regenerate.';
    lines{end+1} = '//';
    lines{end+1} = '// This script creates wire-body centerlines only.';
    lines{end+1} = '// It does not generate tube solids, cope cuts, or end treatments.';
    lines{end+1} = ['// Coordinate transform: frame [Xrear+, Yright+, Zup+] -> Onshape [Xfwd+, Yup+, Zright+] = [-X, Z, Y].'];
    if ~isempty(opts.coordinate_comment)
        lines{end+1} = ['// Note: ' char(opts.coordinate_comment)];
    end
    lines{end+1} = '// ============================================================';
    lines{end+1} = '';
    lines{end+1} = ['annotation { "Feature Type Name" : "' escape_fs_string(opts.feature_name) '" }'];
    lines{end+1} = 'export const fsaeFrame3dSketch = defineFeature(function(context is Context, id is Id, definition is map)';
    lines{end+1} = '    precondition {}';
    lines{end+1} = '    {';

    for i = 1:size(unique_segments, 1)
        n1 = unique_segments(i, 1);
        n2 = unique_segments(i, 2);
        p1 = format_vector_literal(onshape_nodes(n1, :));
        p2 = format_vector_literal(onshape_nodes(n2, :));
        lines{end+1} = sprintf('        opPolyline(context, id + "segment%d", {', i);
        lines{end+1} = sprintf('                "points" : [%s, %s]', p1, p2);
        lines{end+1} = '        });';
    end

    lines{end+1} = '    }, {});';
    lines{end+1} = '';

    output_path = write_fs_file(lines, opts);
    fprintf('Onshape 3D sketch FeatureScript generated: %s\n', output_path);
    fprintf('  Nodes: %d, Elements: %d (unique segments: %d)\n', ...
        size(nodes, 1), size(connectivity, 1), size(unique_segments, 1));
end

function opts = parse_options(options)
    opts = struct();
    opts.output_dir = get_field(options, 'output_dir', fullfile(pwd, 'output'));
    opts.filename = get_field(options, 'filename', 'fsae_frame_onshape_3d_sketch.fs');
    opts.feature_name = get_field(options, 'feature_name', 'FSAE Frame 3D Sketch');
    opts.coordinate_comment = get_field(options, 'coordinate_comment', '');
end

function val = get_field(s, field_name, default_value)
    if isfield(s, field_name)
        val = s.(field_name);
    else
        val = default_value;
    end
end

function onshape_coords = frame_to_onshape(frame_coords)
    onshape_coords = [-frame_coords(:, 1), frame_coords(:, 3), frame_coords(:, 2)];
end

function literal = format_vector_literal(row)
    literal = sprintf('vector(%.9f, %.9f, %.9f) * meter', row(1), row(2), row(3));
end

function escaped = escape_fs_string(value)
    escaped = char(string(value));
    escaped = strrep(escaped, '\', '\\');
    escaped = strrep(escaped, '"', '\"');
end

function output_path = write_fs_file(lines, opts)
    if ~exist(opts.output_dir, 'dir')
        mkdir(opts.output_dir);
    end

    output_path = fullfile(opts.output_dir, opts.filename);
    fid = fopen(output_path, 'w', 'n', 'UTF-8');
    if fid == -1
        error('generate_onshape_3d_sketch:FileError', ...
            'Could not open output file for writing: %s', output_path);
    end

    cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
    fprintf(fid, '%s\n', strjoin(lines, newline));
end
